from pathlib import Path
import csv, hashlib, json, re

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

for case in sorted(path for path in Path('.').iterdir() if (path / 'task.md').is_file()):
    before, after = case / 'before', case / 'after'
    old = {str(p.relative_to(before)): p for p in before.rglob('*') if p.is_file()}
    new = {str(p.relative_to(after)): p for p in after.rglob('*') if p.is_file()}
    observer = json.loads((case / 'observer.json').read_text())
    actions = json.loads((case / 'actions.json').read_text())
    changed = sorted(set(old) "'^ set(new) | {p for p in set(old) & set(new) if sha(old[p]) != sha(new[p])})
    print(case, '"'before', len(old), 'after', len(new), 'changed', changed)
    print('changed-path agreement', changed == actions['changed'] == observer['all_changed_paths'])
    expected = observer['unchanged_record_sha256']
    print('unchanged hashes', set(expected) == set(old), all(sha(old[p]) == sha(new[p]) == h for p,h in expected.items()))
    note = after / 'architecture-note.md'
    print('artifact hash', sha(note) == observer['work_product_sha256'])
    groups = {}
    with (before / 'intake/events.csv').open(newline='') as handle:
        for row in csv.DictReader(handle):
            key = '/'.join(row[k] for k in ('session', 'report', 'employee'))
            groups.setdefault(key, {})[row['event']] = int(row['t_ms'])
    results = {key: events['accepted'] - events['ready'] for key, events in groups.items()}
    kinds = sorted({kind for events in groups.values() for kind in events})
    print('event timing and kinds', results, kinds, results == observer['raw_input_readback']['ready_to_HTTP_accepted_ms'], kinds == observer['raw_input_readback']['recorded_kinds'])
    unresolved = []
    for path, _, fragment in (link.partition('#') for link in re.findall(r'\\]\\((["'^)]+)'"\\)', note.read_text())):
        target = after / path
        if not target.is_file() or (fragment and fragment not in [line.lstrip('# ').lower().replace(' ', '-') for line in target.read_text().splitlines() if line.startswith('#')]):
            unresolved.append(path)
    print('unresolved links', unresolved)
